import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"Teacher Dashboard -> Profile Payment Management / Stripe (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/profile-payment-management.md","filePath":"modules/teacher-dashboard/profile-payment-management.md"}'),i={name:"modules/teacher-dashboard/profile-payment-management.md"};function d(n,e,s,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="teacher-dashboard-profile-payment-management-stripe-deep" tabindex="-1">Teacher Dashboard -&gt; Profile Payment Management / Stripe (deep) <a class="header-anchor" href="#teacher-dashboard-profile-payment-management-stripe-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Profile Payment Management / Stripe (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>profile-payment-management</code><br><strong>Surface:</strong> Payment Management tab inside <code>/teacher-dashboard/settings</code><br><strong>Related routes:</strong> <code>/payment/refresh</code>, <code>/payment/complete</code></p><p>This feature handles instructor Stripe onboarding and payment readiness. It also contains an older transaction-history branch, but the live full history UI now lives on the dedicated transaction-history route.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show Stripe onboarding status.</li><li>Start Stripe onboarding.</li><li>Continue or regenerate onboarding link when setup is incomplete or action is required.</li><li>Refresh Stripe onboarding verification.</li><li>Expose Stripe financial/restriction state from teacher profile.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/PaymentTab.tsx</code></td><td>Main Stripe/payment setup tab</td><td>Uses profile Stripe status and Stripe onboarding mutations. Also loads instructor transactions/stats, though the visible active branch is setup-only.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/StripePaymentRefresh.tsx</code></td><td>Refresh route</td><td>Re-triggers Stripe account link flow.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/StripePaymentComplete.tsx</code></td><td>Completion route</td><td>Verifies onboarding status after Stripe returns to the app.</td></tr><tr><td><code>Frontend/src/graphql/mutations/profile.ts</code></td><td>Profile and Stripe GraphQL</td><td>Defines <code>GET_TEACHER_PROFILE</code>, <code>CREATE_STRIPE_ACCOUNT</code>, <code>REGENERATE_STRIPE_LINK</code>, <code>VERIFY_STRIPE_ONBOARDING</code>, and related profile operations.</td></tr><tr><td><code>Frontend/src/graphql/Queries/transactionQueries.ts</code></td><td>Transaction queries</td><td>Used by <code>PaymentTab.tsx</code> for the dormant/history branch and stats.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="stripe-onboarding-operations" tabindex="-1">Stripe onboarding operations <a class="header-anchor" href="#stripe-onboarding-operations" aria-label="Permalink to &quot;Stripe onboarding operations&quot;">​</a></h3><ul><li><code>GET_TEACHER_PROFILE</code><ul><li>source of: <ul><li><code>onboardingStatus</code></li><li><code>isActive</code></li><li><code>stripeAccount</code></li><li><code>stripeFinancialStatus</code></li></ul></li></ul></li><li><code>CREATE_STRIPE_ACCOUNT</code><ul><li>starts onboarding and returns an onboarding URL</li></ul></li><li><code>REGENERATE_STRIPE_LINK</code><ul><li>continues or repairs onboarding flow</li></ul></li><li><code>VERIFY_STRIPE_ONBOARDING</code><ul><li>refreshes backend Stripe/account state after return from Stripe</li></ul></li></ul><h3 id="transaction-related-operations-used-inside-the-tab" tabindex="-1">Transaction-related operations used inside the tab <a class="header-anchor" href="#transaction-related-operations-used-inside-the-tab" aria-label="Permalink to &quot;Transaction-related operations used inside the tab&quot;">​</a></h3><ul><li><code>GET_INSTRUCTOR_TRANSACTIONS</code></li><li><code>GET_INSTRUCTOR_TRANSACTION_STATS</code></li></ul><p>These are loaded in <code>PaymentTab.tsx</code>, but the current tab state is fixed to <code>&quot;setup&quot;</code>, so the transaction-history branch inside this component is not the main live history UI anymore.</p><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs.js</code></li><li>Relevant mutations: <ul><li><code>createStripeAccount</code></li><li><code>verifyStripeOnboarding</code></li><li><code>regenerateStripeLink</code></li><li><code>setInstructorPayoutToManual</code></li></ul></li><li>Relevant types: <ul><li><code>CreateStripeAccountPayload</code></li><li><code>VerifyStripeOnboardingPayload</code></li><li><code>RegenerateStripeLinkPayload</code></li><li><code>SetPayoutSchedulePayload</code></li></ul></li><li>Relevant query/type data: <ul><li><code>teacherProfile</code> includes onboarding/account/financial status fields</li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers.js</code></li><li>Relevant resolvers: <ul><li><code>Query.teacherProfile</code></li><li><code>Mutation.createStripeAccount</code></li><li><code>Mutation.verifyStripeOnboarding</code></li><li><code>Mutation.regenerateStripeLink</code></li><li><code>Mutation.setInstructorPayoutToManual</code></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/services/stripeService.js</code></td><td>Core Stripe account, onboarding, payout, and payment integration</td></tr><tr><td><code>server/src/graphql/utils/instructorPaymentReady.js</code></td><td>Shared readiness logic that also gates availability</td></tr><tr><td><code>server/src/routes/stripeWebhook.routes.js</code></td><td>Stripe webhook processing</td></tr><tr><td><code>server/src/jobs/payoutJob.js</code></td><td>Instructor payout scheduling</td></tr><tr><td><code>server/src/jobs/t48ChargeJob.js</code></td><td>Deferred charge scheduling</td></tr><tr><td><code>server/src/services/transactionService.js</code></td><td>Transaction ledger entries tied to Stripe events</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Instructor opens Payment Management tab.</li><li><code>GET_TEACHER_PROFILE</code> loads current Stripe onboarding/account state.</li><li>Depending on <code>onboardingStatus</code>, the UI renders a different onboarding-state card.</li><li>Connect / continue / fix actions call: <ul><li><code>CREATE_STRIPE_ACCOUNT</code>, or</li><li><code>REGENERATE_STRIPE_LINK</code></li></ul></li><li>User is redirected to Stripe-hosted onboarding.</li><li>Stripe returns to <code>/payment/complete</code> or <code>/payment/refresh</code>.</li><li>These pages call <code>VERIFY_STRIPE_ONBOARDING</code> or restart onboarding as needed.</li><li>Updated Stripe state is reflected back into <code>teacherProfile</code>, which also drives availability gating and layout-level payment readiness.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li><code>PaymentTab.tsx</code> still imports and queries transaction-history data, but <code>sectionTab</code> is hardcoded to <code>&quot;setup&quot;</code>, so this branch is effectively dormant.</li><li>The real, user-visible full transaction history for instructors is the separate <code>/teacher-dashboard/transaction-history</code> page.</li></ul>',24)])])}const b=t(i,[["render",d]]);export{u as __pageData,b as default};
